this[ "__gx_cache_file" ] = function( _manifestEntry ) {
    if (window.oprt && window.oprt.gameFiles) {

        var url = window.origin + "/" + _manifestEntry["name"];

        const urlParams = new URLSearchParams(window.location.search);
        const gameid = urlParams.get('game');
        const trackid = urlParams.get('track');
        const releaseid = urlParams.get('release');
        if (gameid!=null && trackid!=null && releaseid!=null) {


            url = window.location.origin + "/" + gameid + "/" + trackid + "/" + releaseid + "/" + _manifestEntry["name"];
        }

        console.log("__gx_cache_file for " + url);
      var request = new Request( url );
        let fileId = _manifestEntry["name"] + ":" + _manifestEntry["md5"];

        let response = window.oprt.gameFiles.fetchAndCache(fileId, g_CacheVersion, request).then((r) => {
            r.arrayBuffer().then(
                function () {
                    console.log("fetchAndCache complete for file:id " + fileId);
                    g_CachedFiles[_manifestEntry["name"]] = {
                        "name": _manifestEntry["name"],
                        "md5": _manifestEntry["md5"],
                        "fileId": fileId,
                        "version": g_CacheVersion
                    };
                }
            )



        });

    } // end if
    return Promise.resolve();
}


// --------------------------------------------------------------------------------------------------------------------------------
// --------------------------------------------------------------------------------------------------------------------------------
// --------------------------------------------------------------------------------------------------------------------------------
this["__gx_check_cache"] = function (_fileId, _load_if_not_present) {


    
    var ret = g_CachedFiles[_fileId] != undefined;
    if (_load_if_not_present) 
        console.log("__gx_check_cache for " + _fileId + " cached files " + JSON.stringify(g_CachedFiles) + " manifest files " + JSON.stringify(g_ManifestFiles));

  // if not cached but it is in the manifest then lets cache it
    if (!ret && (g_ManifestFiles[_fileId] != undefined) && _load_if_not_present) {

      this["__gx_cache_file"]( g_ManifestFiles[_fileId] );

  } // end if

  return ret;
} // end __gx_check_cache


// --------------------------------------------------------------------------------------------------------------------------------
// --------------------------------------------------------------------------------------------------------------------------------
this[ "__gx_prepare_cache" ] = function( _version ) {

  g_CacheVersion = _version;
  var promise = new Promise( function( resolve, reject ) {

    // if we have the interface then setup all the files.
    if (window.oprt && window.oprt.gameFiles)  {

      // get everything in manifest
      var manifest = manifestFiles();
      let mFiles = manifest.split(";");
      var manifestMD5 = manifestFilesMD5();

      // get all the cache entries
      window.oprt.gameFiles.keys().then( result => {  

        let cacheEntries = result;
        console.log( "current cache entries are " + JSON.stringify(cacheEntries));

        // create a dictionary of all the names
        var cachedFiles = {};
        let promisesDelete = [];
        for( var n=0; n<cacheEntries.length ; ++n) {
          var entry = cacheEntries[n];
          var name = entry["fileId"];
          var md5 = "";
          var indexOf = name.indexOf(':');
          if (indexOf >= 0) {
            md5 = name.substring( indexOf+1 );
            name = name.substring( 0, indexOf );
          } // end if

          // check to see if item found in mFiles
          var index = mFiles.indexOf( name );
          console.log( "considering file " + name + " for deleting, indexOf is " + index + 
                        " cached MD5 is " + md5 + 
                        " manifest md5 is " + ((index < 0) ? " not present" : manifestMD5[index]));
          if ((index < 0) || (manifestMD5[index] != md5))  {

            // cached file is not in the manifest so lets delete it and forget it exists
            //console.log( "deleting file " + entry["fileId"] + ", version=" + entry["version"])
            promisesDelete.push( window.oprt.gameFiles.delete( entry["fileId"], entry["version"] ) );
          } // end if
          else {
            cachedFiles[ name ] = { 
                                    "name" : name,
                                    "md5" : md5,
                                    "fileId" : entry[ "fileId" ],
                                    "version" : entry[ "version" ],
                                  };
          } // end if
        } // end for
        console.log( "current cache files are " + JSON.stringify(cachedFiles));

        // populate the cache list with the files that are actually cached
        g_CachedFiles = cachedFiles;

        // get a dictionary with all the manifest files in it
        var manFiles = {}
        for( var n=0; n<mFiles.length; ++n ) {
          manFiles[ mFiles[n] ] = {
            "name" : mFiles[n],
            "md5" : manifestMD5[n]
          };
        } // end for
        g_ManifestFiles = manFiles;

        // ensure the game.unx file is cached
        if (g_CachedFiles[ "game.unx" ] == undefined) {
          console.log( "caching game.unx")
          this["__gx_cache_file"]( g_ManifestFiles[ "game.unx"] ).then( result => {
            resolve( { "cachedFiles" : g_CachedFiles, "allFiles" : mFiles });
          });
        } // end if
        else {
          // game.unx is cached we can resolve now
          resolve( { "cachedFiles" : g_CachedFiles, "allFiles" : mFiles });          
        }
      })
      .catch( error => {
        reject( Error("error trying to enumerate cache keys - " + JSON.stringify(error)));
      });
    } // end if
    else {
      reject( Error("unable to cache, API not found"));
    } // end else
  });
  return promise;
} // end __gx_prepare_cache

